func TestReproUnbufferedDeadlock(t *testing.T) {
	ch := make(chan Event)
	done := make(chan struct{})
	go func() { ch <- Event{}; close(done) }()
	select {
	case <-done: t.Fatal("expected block on unbuffered channel")
	case <-time.After(200 * time.Millisecond):
	}
}
